// Des: Tests cloud purge v2: guards, breaker, packs, resume
// Flo: mock cloud + real packs + temp db > purge at different caps > assert what is left and where entries point
// I/O: mock cloud + temp db > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const purg = @import("ru-purg-clou.zig"); const sync = @import("sy-clou-sync.zig"); const cmok = @import("sy-clou-mock.zig"); const outb = @import("sy-clou-outb.zig"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const pack = @import("ru-purg-pack.zig"); const file = @import("st-stor-file.zig"); const hash = @import("ut-hash-dedu.zig");
const allo = std.testing.allocator;
const NOWZ: i64 = 1795528470301;
const OLDA = "runs/20260101T000000Z-a1.pack";
const OLDB = "runs/20260102T000000Z-b2.pack";
const OLDC = "runs/20260103T000000Z-c3.pack";
const OLDD = "runs/20260104T000000Z-d4.pack";
const OLDE = "runs/20260105T000000Z-e5.pack";
const Rigg = struct { tmpz: std.testing.TmpDir, cldz: cmok.Mock, cld2: cmok.Mock, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, synz: sync.Sync, nume: u32 = 0,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.cldz = cmok.Mock.init(allo); self.cld2 = cmok.Mock.init(allo); self.nume = 0; self.synz = .{ .iozz = std.testing.io, .dbzz = &self.dbzz, .dirz = self.dirz, .conf = .{}, .store = self.cldz.store(), .sql2 = self.cldz.sql2() }; self.synz.conf.purg_maxx_pctz = 100; }
pub fn down(self: *Rigg) void { self.cldz.deinit(); self.cld2.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn padz(self: *Rigg) ![]const u8 { const padd = try self.aren.allocator().alloc(u8, 300); @memset(padd, 'x'); return padd; }
pub fn body(self: *Rigg) ![]const u8 { self.nume += 1; return std.fmt.allocPrint(self.aren.allocator(), "page body number {d} {s}", .{ self.nume, try self.padz() }); }
pub fn fiv2(self: *Rigg) !void { for ([_][]const u8{ OLDB, OLDC, OLDD, OLDE }) |nam2| _ = try self.mkpk(nam2, &.{false}); }
pub fn mkpk(self: *Rigg, name: []const u8, live: []const bool) ![]const []const u8 { const aren = self.aren.allocator(); var pars: std.ArrayList(pack.Part) = .empty; for (live) |_| { const bodz = try self.body(); try pars.append(aren, .{ .hexz = try aren.dupe(u8, &hash.hashHexz(bodz)), .gzzz = try file.gzipPack(aren, bodz) }); } const byts = try pack.packBuil(aren, pars.items); const ents = try pack.packPars(aren, byts); const stoz = self.cldz.store(); try stoz.put(stoz.ctx2, aren, std.testing.io, name, byts); var hexs: std.ArrayList([]const u8) = .empty; for (ents, 0..) |entr, indx| { var insz = try self.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz,vfyz) VALUES(?1,?2,?3,?4,1);"); defer insz.fini(); try insz.bindText(1, entr.hexz); try insz.bindText(2, name); try insz.bindIntz(3, @intCast(entr.offs)); try insz.bindIntz(4, @intCast(entr.lenz)); _ = try insz.step(); if (live[indx]) try inde.pageSetz(&self.dbzz, try std.fmt.allocPrint(aren, "http://l/{s}", .{entr.hexz[0..12]}), .{ .hexz = entr.hexz, .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 1, .next = 2 }); try hexs.append(aren, entr.hexz); } return hexs.toOwnedSlice(aren); }
pub fn five(self: *Rigg) !void { for ([_][]const u8{ OLDA, OLDB, OLDC, OLDD, OLDE }) |nam2| _ = try self.mkpk(nam2, &.{false}); }
pub fn scal(self: *Rigg, sqlz: [:0]const u8) !i64 { var stmt = try self.dbzz.prep(sqlz); defer stmt.fini(); if (!try stmt.step()) return -1; return stmt.colzIntz(0); }
pub fn keep(_: *Rigg, mock: *cmok.Mock) ?[]const u8 { var iter = mock.map.keyIterator(); while (iter.next()) |key2| { if (std.mem.startsWith(u8, key2.*, "keep/")) return key2.*; } return null; }
pub fn capzOfzz(self: *Rigg, pctz: u64) u64 { return self.cldz.used() * 100 / pctz; } };
test "below the high mark nothing happens" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.five(); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(50)); try std.testing.expectEqual(purg.Actz.none, rslt.act2); try std.testing.expectEqual(@as(usize, 5), rig3.cldz.map.count()); }
test "at the high mark old packs go oldest first down to the low mark, manifest first, rows cleaned" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.five(); const capz = rig3.capzOfzz(90); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, capz); try std.testing.expectEqual(purg.Actz.purged, rslt.act2); try std.testing.expectEqual(@as(u32, 2), rslt.pac4); try std.testing.expect(rig3.cldz.map.get(OLDA) == null); try std.testing.expect(rig3.cldz.map.get(OLDB) == null); try std.testing.expect(rig3.cldz.map.get(OLDC) != null); try std.testing.expectEqual(@as(usize, 2), rig3.cldz.sawzStmt("INTO cl_purg")); try std.testing.expectEqual(@as(usize, 2), rig3.cldz.sawzStmt("DELETE FROM cl_manif")); try std.testing.expectEqual(@as(i64, 3), try rig3.scal("SELECT count(*) FROM pack;")); try std.testing.expectEqual(@as(i64, 2), try rig3.scal("SELECT count(*) FROM purg WHERE stat=1;")); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM purg WHERE stat=0;")); const agai = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, capz); try std.testing.expectEqual(purg.Actz.none, agai.act2); }
test "the young guard: packs under 90 days are never purged, the result says young" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); for ([_][]const u8{ "runs/20261120T000000Z-a1.pack", "runs/20261121T000000Z-b2.pack", "runs/20261122T000000Z-c3.pack" }) |nam2| _ = try rig3.mkpk(nam2, &.{false}); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(95)); try std.testing.expectEqual(purg.Actz.young, rslt.act2); try std.testing.expectEqual(@as(u32, 0), rslt.pac4); try std.testing.expectEqual(@as(usize, 3), rig3.cldz.map.count()); }
test "a pack with an unreadable name date is treated as young and kept" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.mkpk("runs/mystery.pack", &.{false}); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(95)); try std.testing.expectEqual(purg.Actz.young, rslt.act2); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.map.count()); }
test "the breaker: one run frees at most purg_maxx_pctz of the cap, says limited, the next run continues" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.five(); rig3.synz.conf.purg_maxx_pctz = 10; const capz = rig3.capzOfzz(100); const rsl1 = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, capz); try std.testing.expectEqual(@as(u32, 1), rsl1.pac4); try std.testing.expect(rsl1.limd); try std.testing.expectEqual(@as(usize, 4), rig3.cldz.map.count()); const rsl2 = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, capz); try std.testing.expectEqual(@as(u32, 1), rsl2.pac4); try std.testing.expectEqual(@as(usize, 3), rig3.cldz.map.count()); }
test "the latest version survives: live files move into one verified keep pack, rows follow, then the old pack goes" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.synz.vnam = "mock1"; const hexs = try rig3.mkpk(OLDA, &.{ true, false }); try rig3.fiv2(); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(90)); try std.testing.expectEqual(@as(u32, 1), rslt.keep); try std.testing.expectEqual(@as(u32, 1), rslt.kept); try std.testing.expect(rig3.cldz.map.get(OLDA) == null); const kpkz = rig3.keep(&rig3.cldz).?; var sel1 = try rig3.dbzz.prep("SELECT packk,vend,vfyz FROM pack WHERE hexz=?1;"); defer sel1.fini(); try sel1.bindText(1, hexs[0]); try std.testing.expect(try sel1.step()); try std.testing.expectEqualStrings(kpkz, sel1.colzText(0)); try std.testing.expectEqualStrings("mock1", sel1.colzText(1)); try std.testing.expectEqual(NOWZ, sel1.colzIntz(2)); var sel2 = try rig3.dbzz.prep("SELECT 1 FROM pack WHERE hexz=?1;"); defer sel2.fini(); try sel2.bindText(1, hexs[1]); try std.testing.expect(!try sel2.step()); const back = try sync.res3(&rig3.synz, rig3.aren.allocator(), hexs[0][0..64].*); try std.testing.expect(std.mem.startsWith(u8, back, "page body number 1")); try std.testing.expect(rig3.cldz.sawzStmt("INTO cl_manif") >= 1); }
test "keep packs are copied to the second store; a copy failure is queued and retried" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.synz.copy = rig3.cld2.store(); _ = try rig3.mkpk(OLDA, &.{true}); try rig3.fiv2(); rig3.cld2.stoo = true; const rsl1 = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(90)); try std.testing.expectEqual(@as(u32, 1), rsl1.keep); try std.testing.expectEqual(@as(usize, 0), rig3.cld2.map.count()); try std.testing.expectEqual(@as(i64, 1), try outb.outbCont(&rig3.dbzz, 0)); rig3.cld2.stoo = false; _ = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ + 3600000 * 24, 0); try std.testing.expectEqual(@as(usize, 1), rig3.cld2.map.count()); try std.testing.expect(rig3.cld2.map.get(rig3.keep(&rig3.cldz).?) != null); try std.testing.expectEqual(@as(i64, 0), try outb.outbCont(&rig3.dbzz, 0)); }
test "a keep pack with more than 30 percent dead weight is rewritten with the live entries only" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.synz.copy = rig3.cld2.store(); const hexs = try rig3.mkpk("keep/20260601T000000Z-k1.pack", &.{ true, false, false }); const oldz = rig3.cldz.map.get("keep/20260601T000000Z-k1.pack").?; const sto2 = rig3.cld2.store(); try sto2.put(sto2.ctx2, rig3.aren.allocator(), std.testing.io, "keep/20260601T000000Z-k1.pack", oldz); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, 0); try std.testing.expectEqual(@as(u32, 1), rslt.comp); try std.testing.expect(rig3.cldz.map.get("keep/20260601T000000Z-k1.pack") == null); try std.testing.expect(rig3.cld2.map.get("keep/20260601T000000Z-k1.pack") == null); const newk = rig3.keep(&rig3.cldz).?; try std.testing.expect(std.mem.endsWith(u8, newk, ".pack")); try std.testing.expectEqual(@as(usize, 1), rig3.cldz.map.count()); const back = try sync.res3(&rig3.synz, rig3.aren.allocator(), hexs[0][0..64].*); try std.testing.expect(std.mem.startsWith(u8, back, "page body number 1")); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT count(*) FROM pack;")); }
test "a keep pack that is all live is left alone, an orphan keep pack with no rows is removed" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.mkpk("keep/20260601T000000Z-k1.pack", &.{ true, true }); const stoz = rig3.cldz.store(); try stoz.put(stoz.ctx2, rig3.aren.allocator(), std.testing.io, "keep/20260602T000000Z-orph.pack", "SCRAPK1\n"); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, 0); try std.testing.expectEqual(@as(u32, 1), rslt.comp); try std.testing.expect(rig3.cldz.map.get("keep/20260601T000000Z-k1.pack") != null); try std.testing.expect(rig3.cldz.map.get("keep/20260602T000000Z-orph.pack") == null); }
test "crash safety: a pack left in purging state is finished at the next run" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.mkpk(OLDA, &.{false}); try rig3.dbzz.exec("INSERT INTO purg(packz,timz,ents,stat) VALUES('runs/20260101T000000Z-a1.pack',5,1,0);"); const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, 0); try std.testing.expectEqual(purg.Actz.none, rslt.act2); try std.testing.expect(rig3.cldz.map.get(OLDA) == null); try std.testing.expectEqual(@as(i64, 1), try rig3.scal("SELECT stat FROM purg;")); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM pack;")); }
test "if the manifest cannot be written, nothing is deleted and no purge is recorded as done" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.five(); rig3.cldz.sqlo = true; try std.testing.expectError(error.CloudSql, purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(90))); try std.testing.expectEqual(@as(usize, 5), rig3.cldz.map.count()); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM purg;")); try std.testing.expectEqual(@as(i64, 5), try rig3.scal("SELECT count(*) FROM pack;")); }
test "mode upgr only reports, deletes nothing" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try rig3.five(); rig3.synz.conf.clou_poli_mode = "upgr"; const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(90)); try std.testing.expectEqual(purg.Actz.upgr, rslt.act2); try std.testing.expectEqual(@as(usize, 5), rig3.cldz.map.count()); }
test "a corrupt live entry with no local file keeps the pack and counts it as bad; with a local file it is repaired" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const hexs = try rig3.mkpk(OLDA, &.{true}); const stoz = rig3.cldz.store(); try stoz.put(stoz.ctx2, rig3.aren.allocator(), std.testing.io, OLDA, "SCRAPK1\ngarbage that is not the real entry bytes at all"); try rig3.fiv2(); const rsl1 = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(90)); try std.testing.expectEqual(@as(u32, 1), rsl1.bads); try std.testing.expect(rig3.cldz.map.get(OLDA) != null); const rawd = try std.fs.path.join(rig3.aren.allocator(), &.{ rig3.dirz, "raw" }); const bodz = try std.fmt.allocPrint(rig3.aren.allocator(), "page body number 1 {s}", .{try rig3.padz()}); const sav2 = try file.fileSave(allo, std.testing.io, rawd, bodz); try std.testing.expectEqualStrings(hexs[0], &sav2.hexz); const rsl2 = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(90)); try std.testing.expectEqual(@as(u32, 0), rsl2.bads); try std.testing.expect(rig3.cldz.map.get(OLDA) == null); const back = try sync.res3(&rig3.synz, rig3.aren.allocator(), hexs[0][0..64].*); try std.testing.expectEqualStrings(bodz, back); }
test "dry run reports the plan and changes nothing" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.mkpk(OLDA, &.{ true, false }); try rig3.fiv2(); rig3.synz.dryz = true; const rslt = try purg.purgRunz(&rig3.synz, rig3.aren.allocator(), NOWZ, rig3.capzOfzz(90)); try std.testing.expect(rslt.plan); try std.testing.expect(rslt.pac4 >= 1); try std.testing.expectEqual(@as(u32, 1), rslt.kept); try std.testing.expectEqual(@as(usize, 5), rig3.cldz.map.count()); try std.testing.expectEqual(@as(usize, 0), rig3.cldz.stm2.items.len); try std.testing.expectEqual(@as(i64, 0), try rig3.scal("SELECT count(*) FROM purg;")); }
